#!/usr/bin/env pwsh\n\n<#\n.SYNOPSIS\n    Phase 78: Complete RAG Brain Deployment\n    \n.DESCRIPTION\n    Deploys the complete Phase 73-78 RAG brain pipeline:\n    1. Tests infrastructure\n    2. Runs Phase 72 topology\n    3. Runs Phase 73 clustering\n    4. Runs Phase 73 summarization\n    5. Reports statistics\n    \n.EXAMPLE\n    .\\phase78-deploy.ps1\n    .\\phase78-deploy.ps1 -Cycle 2\n    .\\phase78-deploy.ps1 -SkipPhase72\n#>\n\nparam(\n    [int]$Cycle = 1,\n    [switch]$SkipPhase72,\n    [switch]$SkipTest\n)\n\n$ErrorActionPreference = \"Stop\"\n$ProgressPreference = \"SilentlyContinue\"\n\nfunction Write-Header {\n    param([string]$Text)\n    Write-Host \"`n\" -NoNewline\n    Write-Host \"═\" * 60 -ForegroundColor Cyan\n    Write-Host \"  $Text\" -ForegroundColor Cyan\n    Write-Host \"═\" * 60 -ForegroundColor Cyan\n}\n\nfunction Write-Step {\n    param([string]$Text, [int]$Number, [int]$Total)\n    Write-Host \"`n[$Number/$Total] $Text\" -ForegroundColor Green\n}\n\nfunction Write-Success {\n    param([string]$Text)\n    Write-Host \"✓ $Text\" -ForegroundColor Green\n}\n\nfunction Write-Error-Custom {\n    param([string]$Text)\n    Write-Host \"✗ $Text\" -ForegroundColor Red\n}\n\nfunction Write-Info {\n    param([string]$Text)\n    Write-Host \"ℹ $Text\" -ForegroundColor Yellow\n}\n\n# Main deployment\ntry {\n    Write-Header \"Phase 78: RAG Brain Deployment\"\n    Write-Host \"Cycle: $Cycle\" -ForegroundColor Cyan\n    Write-Host \"Skip Phase 72: $SkipPhase72\" -ForegroundColor Cyan\n    Write-Host \"Skip Test: $SkipTest\" -ForegroundColor Cyan\n    \n    $startTime = Get-Date\n    \n    # Step 1: Test Infrastructure\n    if (-not $SkipTest) {\n        Write-Step \"Testing Infrastructure\" 1 5\n        \n        Write-Info \"Running infrastructure tests...\"\n        $env:PHASE72_CYCLE = $Cycle\n        node scripts/phase78-test-brain.mjs\n        \n        if ($LASTEXITCODE -ne 0) {\n            Write-Error-Custom \"Infrastructure test failed\"\n            exit 1\n        }\n        Write-Success \"Infrastructure test passed\"\n    }\n    \n    # Step 2: Phase 72 Topology\n    if (-not $SkipPhase72) {\n        Write-Step \"Running Phase 72 Topology\" 2 5\n        \n        Write-Info \"Scanning and vectorizing errors...\"\n        $env:PHASE72_CYCLE = $Cycle\n        npm run phase72:topology\n        \n        if ($LASTEXITCODE -ne 0) {\n            Write-Error-Custom \"Phase 72 topology failed\"\n            exit 1\n        }\n        Write-Success \"Phase 72 topology complete\"\n    }\n    \n    # Step 3: Phase 73 Clustering\n    Write-Step \"Running Phase 73 Clustering\" 3 5\n    \n    Write-Info \"Clustering similar errors...\"\n    $env:PHASE72_CYCLE = $Cycle\n    $env:PHASE73_SIM_THRESHOLD = \"0.92\"\n    npm run phase73:cluster\n    \n    if ($LASTEXITCODE -ne 0) {\n        Write-Error-Custom \"Phase 73 clustering failed\"\n        exit 1\n    }\n    Write-Success \"Phase 73 clustering complete\"\n    \n    # Step 4: Phase 73 Summarization\n    Write-Step \"Running Phase 73 Summarization\" 4 5\n    \n    Write-Info \"Generating cluster summaries...\"\n    $env:PHASE72_CYCLE = $Cycle\n    $env:PHASE73_MAX_CLUSTERS = \"100\"\n    npm run phase73:summarize\n    \n    if ($LASTEXITCODE -ne 0) {\n        Write-Error-Custom \"Phase 73 summarization failed\"\n        exit 1\n    }\n    Write-Success \"Phase 73 summarization complete\"\n    \n    # Step 5: Report Statistics\n    Write-Step \"Reporting Statistics\" 5 5\n    \n    Write-Info \"Querying topology statistics...\"\n    \n    # Query Postgres for stats\n    $dbUrl = $env:DATABASE_URL\n    if (-not $dbUrl) {\n        Write-Error-Custom \"DATABASE_URL not set\"\n        exit 1\n    }\n    \n    # Create a simple Node script to query stats\n    $statsScript = @\"\nimport { Pool } from 'pg';\nimport 'dotenv/config';\n\nconst pool = new Pool({ connectionString: process.env.DATABASE_URL });\n\n(async () => {\n  try {\n    const errors = await pool.query(\n      'SELECT COUNT(*) as count FROM phase72_error WHERE phase = 72 AND cycle = \\$1',\n      [$Cycle]\n    );\n    const clusters = await pool.query(\n      'SELECT COUNT(*) as count FROM phase72_cluster WHERE phase = 72 AND cycle = \\$1',\n      [$Cycle]\n    );\n    const summaries = await pool.query(\n      `SELECT COUNT(*) as count FROM phase72_cluster_summary s\n       JOIN phase72_cluster c ON c.id = s.cluster_id\n       WHERE c.phase = 72 AND c.cycle = \\$1`,\n      [$Cycle]\n    );\n    const topCodes = await pool.query(\n      `SELECT code, COUNT(*) as count FROM phase72_error\n       WHERE phase = 72 AND cycle = \\$1\n       GROUP BY code ORDER BY count DESC LIMIT 5`,\n      [$Cycle]\n    );\n    \n    console.log('\\n📊 Topology Statistics');\n    console.log('Errors:', errors.rows[0].count);\n    console.log('Clusters:', clusters.rows[0].count);\n    console.log('Summaries:', summaries.rows[0].count);\n    console.log('\\nTop Error Codes:');\n    topCodes.rows.forEach((row, idx) => {\n      console.log(`  \\${idx + 1}. \\${row.code}: \\${row.count} errors`);\n    });\n  } catch (err) {\n    console.error('Stats query failed:', err.message);\n  } finally {\n    await pool.end();\n  }\n})();\n\"@\n    \n    $statsScript | node -\n    \n    # Calculate duration\n    $duration = (Get-Date) - $startTime\n    \n    Write-Header \"Deployment Complete\"\n    Write-Success \"Phase 78 RAG Brain deployment successful\"\n    Write-Host \"Duration: $($duration.TotalSeconds.ToString('F1'))s\" -ForegroundColor Cyan\n    \n    Write-Host \"`nNext steps:\" -ForegroundColor Green\n    Write-Host \"  1. Test fix suggestions:\" -ForegroundColor Green\n    Write-Host \"     node scripts/phase78-suggest-fix.mjs \\\"TS2304\\\" \\\"Cannot find name\\\" \\\"src/routes/+page.svelte\\\" 1 1\" -ForegroundColor Gray\n    Write-Host \"  2. Integrate with ACE for autonomous fixing\" -ForegroundColor Green\n    Write-Host \"  3. Monitor error reduction over time\" -ForegroundColor Green\n    Write-Host \"`n\" -NoNewline\n    \n} catch {\n    Write-Error-Custom \"Deployment failed: $_\"\n    exit 1\n}\n"}
